feed:
{{ site.title | xml_escape }} {{ include.title }}
{{ site.tagline | xml_escape }}


{{ page.url | prepend:site.web_url | xml_escape }}
{{ site.time | date_to_xmlschema }}

	{{ site.author | xml_escape }}

{{ site.feed.icon | prepend:site.web_url | xml_escape }}
{{ site.feed.logo | prepend:site.web_url | xml_escape }}
Jekyll

{%- assign collection = include.collection | sort:"date" | reverse -%}
{%- if site.feed.length >= 0 -%}
	{%- assign collection = collection | limit:site.feed.length -%}
{%- endif -%}

{%- for i in collection -%}{%- unless i.date -%}{%- continue -%}{%- endunless -%}
	{%- assign title = i.title | default:i.slug | strip_html | xml_escape -%}
	{{ title }}

	{%- comment -%}
		The following `id` is generated adherent to the method specified in
			https://web.archive.org/web/20110915110202if_/http://diveintomark.org/archives/2004/05/28/howto-atom-id
		NOTE TO SELF: The publishing date and slug of a page, once created,
		_really_ shouldn't change. Change the `title:` if you must.
	{%- endcomment -%}
	{%- assign id_date = i.date | date:",%Y-%m-%d:" -%}
	{%- assign id_url = i.url | replace:"#","/" -%}
	{%- assign id = id_url | prepend:id_date | prepend:site.domain | prepend:"tag:" -%}
	{{ id | xml_escape }}

	{{ i.date | date_to_xmlschema }}
	{{ i.updated | default:i.date | date_to_xmlschema }}

	{%- assign banner = i.image -%}
	{%- unless banner == site.banner -%}
		{%- unless banner contains "://" -%}
			{%- assign banner = banner | prepend:site.web_url -%}
		{%- endunless -%}
		{%- assign banner = banner | xml_escape -%}


	{%- endunless -%}

	{{ i.description | default:i.excerpt | strip_html
		| truncatewords:site.excerpt_max_words | xml_escape | strip }}
	{{ i.content | strip | xml_escape }}
{%- endfor -%}
